import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        long n = fs.nextLong();
        long k = fs.nextLong();

        long m = 0;
        long fact = 1;
        // We need to find m such that m! >= k.
        // Since n, k <= 10^9, m <= 13 (13! > 10^9, 12! < 10^9).
        // We must also ensure m <= n.
        while (m < n && fact < k) {
            m++;
            fact *= m;
        }

        if (fact < k) {
            System.out.println(-1);
            return;
        }

        // The first (n - m) elements are fixed: 1, 2, ..., n-m.
        // The last m elements are a permutation of {n-m+1, ..., n}.
        // We need to find the (k-1)-th permutation of these m elements.
        long fixedCount = n - m;

        // Generate lucky numbers up to n.
        List<Long> luckyNumbers = new ArrayList<>();
        generateLucky(0, n, luckyNumbers);
        Collections.sort(luckyNumbers);

        // Count lucky numbers <= fixedCount.
        int count = 0;
        for (long lucky : luckyNumbers) {
            if (lucky <= fixedCount) {
                count++;
            } else {
                break;
            }
        }

        // Generate the k-th permutation of the last m elements.
        List<Long> remaining = new ArrayList<>();
        for (long i = fixedCount + 1; i <= n; i++) {
            remaining.add(i);
        }

        long k0 = k - 1; // 0-based index
        // Precompute factorials for m down to 1.
        long[] factArr = new long[(int)m + 1];
        factArr[0] = 1;
        for (int i = 1; i <= m; i++) {
            factArr[i] = factArr[i-1] * i;
        }

        // Map for quick lookup of lucky numbers (only needed for the suffix range, but set is small).
        Set<Long> luckySet = new HashSet<>(luckyNumbers);

        for (int i = 0; i < m; i++) {
            int remSize = m - i;
            long currentFact = factArr[remSize - 1];
            int idx = (int)(k0 / currentFact);
            k0 %= currentFact;

            long val = remaining.remove(idx);
            long pos = fixedCount + 1 + i;
            if (luckySet.contains(pos) && luckySet.contains(val)) {
                count++;
            }
        }

        System.out.println(count);
    }

    static void generateLucky(long cur, long limit, List<Long> list) {
        if (cur > limit) return;
        if (cur != 0) list.add(cur);
        if (cur > limit / 10) return; // Optimization to avoid overflow/extra calls
        generateLucky(cur * 10 + 4, limit, list);
        generateLucky(cur * 10 + 7, limit, list);
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() {
            while (!st.hasMoreTokens())
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            return st.nextToken();
        }
        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
